/**
 * Type declarations for vshymanskyy/randomart evaluation functions
 */

import "./randomart-eval.js"

declare module "./randomart-eval.js" {
   /**
    * Compiled evaluator function that computes RGB values at coordinates.
    *
    * @param x - X coordinate in range [-1, 1]
    * @param y - Y coordinate in range [-1, 1]
    * @returns RGB color values in range [-1, 1] as [r, g, b]
    */
   export type EvaluatorFunction = (x: number, y: number) => [number, number, number]

   /**
    * Create an evaluator function from a formula string.
    *
    * The formula is generated by ExpressionTree.toString() and contains
    * function calls like Const(), Well(), Sin(), Mix(), etc.
    *
    * @param formula - Formula string from ExpressionTree.toString()
    * @returns Compiled function that evaluates coordinates to RGB values
    */
   export function getEvaluator(formula: string): EvaluatorFunction
}
